<div class="page-heading"><div><div class="eyebrow">PENCATATAN PERIODE</div><h1>Transaksi Penghasilan<span class="heading-dot">.</span></h1><p>Rincian pendapatan dan potongan setiap karyawan.</p></div><a href="<?=url('transaksi/form',$period)?>" class="btn btn-primary"><?=icon('plus')?> Transaksi baru</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<section class="stats-grid"><article class="stat-card"><div class="stat-top">Transaksi tercatat<span class="stat-icon mint"><?=icon('receipt')?></span></div><strong class="stat-value"><?=e($summary['n'])?></strong><span class="muted-small"><?=month_name($period['bulan'])?> <?=$period['tahun']?></span></article><?php foreach(['gross'=>'Penghasilan Bruto','deductions'=>'Total Potongan','net'=>'Penghasilan Bersih'] as $f=>$label):?><article class="stat-card"><div class="stat-top"><?=e($label)?><span class="stat-icon <?=$f==='net'?'emerald':'sage'?>"><?=icon($f==='net'?'check':'wallet')?></span></div><strong class="stat-value"><?=money($summary[$f])?></strong><span class="muted-small">Sesuai filter terpilih</span></article><?php endforeach;?></section>
<section class="surface"><form class="filter-bar payroll-filters uniform-filters" method="get"><div class="field"><label for="list-month" class="form-label">Bulan</label><select id="list-month" class="form-select" name="bulan"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>"<?=selected($period['bulan'],$m)?>><?=month_name($m)?></option><?php endfor;?></select></div><div class="field"><label for="list-year" class="form-label">Tahun</label><input class="form-control" id="list-year" type="number" min="1900" max="9999" name="tahun" value="<?=$period['tahun']?>"></div><div class="field wide"><label for="list-department" class="form-label">Bagian</label><select id="list-department" class="form-select" name="bagian"><option value="">Semua bagian</option><?php foreach($departments as $d):?><option value="<?=e($d['kd_bagian'])?>"<?=selected($period['bagian'],$d['kd_bagian'])?>><?=e($d['nama_bagian'])?></option><?php endforeach;?></select></div><div class="field wide"><label for="list-search" class="form-label">Cari karyawan</label><input class="form-control" id="list-search" list="list-search-data" name="q" placeholder="NIP atau nama" value="<?=e($search)?>"></div><button class="btn btn-primary" type="submit"><?=icon('search')?> Tampilkan</button></form><div class="table-responsive"><table class="table app-table"><thead><tr><th>Karyawan</th><th>Bagian</th><th class="text-end">Bruto</th><th class="text-end">Potongan</th><th class="text-end">Bersih</th><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><div class="employee-cell"><span class="avatar small"><?=e(mb_substr($row['nama'],0,1))?></span><span><strong><?=e($row['nama'])?></strong><small><?=e($row['nip'])?></small></span></div></td><td><span class="department-tag"><?=e($row['nama_bagian'])?></span></td><td class="text-end amount"><?=money($row['tpenghasilan'])?></td><td class="text-end amount"><?=money($row['tpotongan'])?></td><td class="text-end amount text-green fw-bold"><?=money($row['tbersih'])?></td><td><div class="row-actions"><a href="<?=e(url('transaksi/form',['id'=>$row['id']]))?>" class="icon-button" aria-label="Ubah transaksi <?=e($row['nip'])?>"><?=icon('edit')?></a><a href="<?=url('laporan',['type'=>'slip_karyawan','bulan'=>(int)$row['bulan'],'tahun'=>$row['tahun'],'nip'=>$row['nip'],'view'=>1])?>" class="icon-button" aria-label="Slip <?=e($row['nip'])?>"><?=icon('print')?></a><form method="post" data-confirm="Hapus transaksi <?=e($row['nip'])?> pada periode ini?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$row['id']?>"><button type="submit" class="icon-button danger" aria-label="Hapus transaksi <?=e($row['nip'])?>"><?=icon('trash')?></button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6"><div class="empty-state"><?=icon('receipt')?><strong>Belum ada transaksi yang sesuai</strong><p>Ubah filter atau mulai transaksi penghasilan baru.</p><a class="btn btn-primary btn-sm" href="<?=url('transaksi/form',$period)?>"><?=icon('plus')?> Buat transaksi</a></div></td></tr><?php endif;?></tbody><tfoot><tr><td colspan="2">Total seluruh hasil filter</td><td class="text-end amount"><?=money($summary['gross'])?></td><td class="text-end amount"><?=money($summary['deductions'])?></td><td class="text-end amount fw-bold text-green"><?=money($summary['net'])?></td><td></td></tr></tfoot></table></div><?php if((int)$summary['n']>25):?><div class="table-pagination"><span>Halaman <?=$page?> dari <?=(int)ceil($summary['n']/25)?></span><div><?php if($page>1):?><a class="btn btn-light btn-sm" href="<?=url('transaksi',[...$period,'q'=>$search,'page'=>$page-1])?>">Sebelumnya</a><?php endif;?><?php if($page*25<(int)$summary['n']):?><a class="btn btn-light btn-sm" href="<?=url('transaksi',[...$period,'q'=>$search,'page'=>$page+1])?>">Berikutnya</a><?php endif;?></div></div><?php endif;?></section>
<datalist id="list-search-data"><?php foreach($searchOptions as $option):?><option value="<?=e($option['nip'])?>"><?=e($option['nama'])?></option><?php endforeach;?></datalist>
